import type { IngredientFlag, RatingRecord } from '../ratingRecord';

const UNVERIFIED = 'unverified' as const;
const BRAND = 'Herb Pharm';
const ADULT = 'adult' as const;
const KIDS = 'kids' as const;
const SUPPLEMENT = 'Supplement' as const;

function flag(panel: string, name: string, grade: IngredientFlag['riskLevel'], counts: boolean, lock: 't215' | 'prior'): IngredientFlag {
  const meth = lock === 't215'
    ? (grade === 'limited'
      ? 'Methodology §5 Limited (founder lock t215u). Counts toward the 3+ Limited stack.'
      : 'Methodology §5 Cleared (founder lock t215u). Does not count toward the t137u stack.')
    : (grade === 'limited'
      ? 'Methodology §5 Limited. Counts toward the 3+ Limited stack.'
      : grade === 'moderate'
      ? 'Methodology §5 Caution. Does not count toward the t137u stack.'
      : 'Methodology §5 Cleared. Does not count toward the t137u stack.');
  return { name, riskLevel: grade, stackCountExempt: !counts, source: `${panel}; ${meth}` };
}

